export async function getIssueParticipants(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly UserId[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "comment:read", issueResource(issue));

  const candidateIds = new Set<UserId>([
    issue.authorId,
    ...(issue.assigneeId === null ? [] : [issue.assigneeId]),
    ...(await commentRepo.listCommentAuthorIds(orgId, issueId)),
  ]);

  const memberships = await Promise.all(
    [...candidateIds].map((userId) => memberRepo.findMember(orgId, userId)),
  );

  return [...candidateIds].filter((_, index) => memberships[index]?.status === "active");
}

function isPastEditWindow(comment: Comment): boolean {
  const posted = new Date(comment.createdAt).getTime();
  return Date.now() - posted > EDIT_WINDOW_MS;
}

